-- =============================================================================
-- 510 — LE CAHIER D'EXERCICES DE 2DE (partie 12)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 510 --niveau 2de --fichiers ses.n2,snt.n1 --suffixe 12 > supabase/contenu/510_exercices_2de_12.sql
--
-- 63 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   ses.n2                  33 exercices · 11 chapitres
--   snt.n1                  30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('52ea8d1e-7aca-575d-9c1a-3319e3e8b0e5'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Nour apprend à dire merci","competence":"analyser-texte","situation":"Nour a 7 ans. Au fil d’une semaine, plusieurs personnes et plusieurs lieux lui apprennent à bien se comporter. Lis le récit de ses journées, puis repère qui lui apprend quoi, et comment.","documents":[{"id":"nour","type":"texte","genre":"recit","titre":"Les journées de Nour","auteur":"Texte écrit pour l’exercice","blocs":["Chaque soir, à table, le père de Nour lui répète : « On dit merci quand on reçoit quelque chose. » Quand elle y pense, il la félicite. Quand elle oublie, il lui fait recommencer.","À l’école, son institutrice distribue des bons points aux élèves qui rangent leur place avant la sortie.","Le mercredi, Nour regarde son dessin animé préféré, où l’héroïne dit toujours bonjour aux voisins. Nour s’est mise à le faire aussi, sans que personne le lui demande."]}],"questions":[{"enonce":"Dans le premier paragraphe, touche le mot qui montre qu’un comportement est récompensé.","aide":"Cherche le verbe qui dit que son père lui fait plaisir quand elle respecte la règle.","type":"zone","document":"nour","multiple":false},{"enonce":"Relie chaque situation à l’instance de socialisation qui la porte.","aide":"Pense au lieu ou à la personne qui transmet : maison, classe, écran.","type":"association","gauche":[{"id":"g0","texte":"Son père lui répète de dire merci"},{"id":"g1","texte":"Son institutrice distribue des bons points"},{"id":"g2","texte":"Elle imite l’héroïne de son dessin animé"}],"droite":[{"id":"d0","texte":"Les médias"},{"id":"d1","texte":"La famille"},{"id":"d2","texte":"L’école"}]},{"enonce":"Range chaque scène selon la manière dont la norme est transmise.","aide":"Explicite : on énonce, on récompense, on sanctionne. Implicite : on imite ce qu’on voit.","type":"categories","categories":[{"id":"c0","texte":"Inculcation explicite"},{"id":"c1","texte":"Imprégnation implicite"}],"items":[{"id":"i0","texte":"L’institutrice donne un bon point pour une place rangée"},{"id":"i1","texte":"Nour copie l’héroïne sans qu’on le lui demande"},{"id":"i2","texte":"Le père répète la règle et félicite Nour"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24"]},"explication":"Le verbe « **félicite** » montre une récompense : on valorise le bon comportement pour qu’il se répète."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Le père relève de la **famille**, l’institutrice de l’**école**, le dessin animé des **médias**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0"}},"explication":"Quand on énonce, récompense ou sanctionne, c’est de l’**inculcation explicite** ; quand l’enfant copie ce qu’il voit, c’est de l’**imprégnation implicite**."}]$ex$::jsonb),
  ('52ea8d1e-7aca-575d-9c1a-3319e3e8b0e5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mehdi entre sa famille, son lycée et ses copains","competence":"lire-tableau","situation":"Mehdi a 16 ans. Il reçoit chaque jour des messages différents selon les personnes et les lieux qu’il fréquente. Le tableau les rassemble : à toi de les analyser.","documents":[{"id":"mehdi","type":"tableau","titre":"Ce que Mehdi entend, et d’où","source":"Situation imaginée pour l’exercice.","colonnes":["Instance de socialisation","Moment fort","Ce que Mehdi y entend"],"enteteLignes":true,"lignes":[["Sa famille","L’enfance","« Sois poli avec tout le monde. »"],["Son lycée","L’enfance et l’adolescence","« Travaille régulièrement. »"],["Ses copains","L’adolescence","« Ne fais pas le premier de la classe. »"],["Les vidéos qu’il regarde","Tous les âges","« Fais ce qui te plaît. »"],["Son stage en entreprise","L’âge adulte","« Sois ponctuel. »"]]}],"questions":[{"enonce":"Touche le moment fort de l’instance « groupes de pairs » (ses copains).","aide":"Les pairs sont les personnes du même âge que Mehdi : trouve la ligne « Ses copains ».","type":"zone","document":"mehdi","multiple":false},{"enonce":"Quels deux messages de ce tableau se contredisent le plus nettement ?","aide":"Cherche un message qui pousse à travailler et un autre qui décourage de bien réussir.","type":"choix","options":[{"id":"a","texte":"Sa famille et son stage"},{"id":"b","texte":"Son stage et les vidéos"},{"id":"c","texte":"Son lycée et ses copains"},{"id":"d","texte":"Sa famille et son lycée"}],"multiple":false},{"enonce":"Range chaque apprentissage selon la socialisation qu’il illustre.","aide":"La primaire se joue dans l’enfance ; la secondaire à l’âge adulte (travail, couple, associations).","type":"categories","categories":[{"id":"c0","texte":"Socialisation primaire"},{"id":"c1","texte":"Socialisation secondaire"}],"items":[{"id":"i0","texte":"Découvrir le fonctionnement d’un syndicat à 30 ans"},{"id":"i1","texte":"Prendre les goûts alimentaires de sa famille"},{"id":"i2","texte":"Apprendre les usages d’un premier emploi"},{"id":"i3","texte":"Apprendre à parler et à dire bonjour avec ses parents"}]},{"enonce":"Complète la phrase.","aide":"Pense à « dire bonjour » : on ne se force pas à le faire.","type":"trous","segments":["Une norme ",0," n’est plus ressentie comme une ",1," : on ne se force plus à la respecter."],"banque":["récompense","contrainte","intériorisée","sanction"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Les groupes de pairs ont leur moment fort à l’**adolescence**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le lycée dit « travaille régulièrement » et les copains « ne fais pas le premier de la classe » : les instances peuvent transmettre des messages **contradictoires**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Dans l’enfance, la famille façonne la langue, les manières et les goûts : c’est la **primaire**. Le travail et les associations de l’âge adulte relèvent de la **secondaire**."},{"cle":{"type":"trous","trous":[["interiorisee","interiorise"],["contrainte"]]},"affichage":"intériorisée · contrainte","explication":"Ce qui est **intériorisé** cesse d’être ressenti comme une **contrainte** : la norme est devenue une manière naturelle d’agir."}]$ex$::jsonb),
  ('52ea8d1e-7aca-575d-9c1a-3319e3e8b0e5'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Samia, entre les parents et les copines","competence":"analyser-document","situation":"Samia, 15 ans, reçoit des messages contraires de plusieurs côtés. Lis son témoignage, puis observe le schéma de ses influences.","documents":[{"id":"temoin","type":"texte","genre":"recit","titre":"Le témoignage de Samia","auteur":"Témoignage écrit pour l’exercice","blocs":["À la maison, personne ne m’a jamais dit « étudie ». Ma sœur aînée révise chaque soir sur la table de la cuisine, et je l’ai toujours imitée.","Avec mes copines, c’est autre chose : celles qui lèvent trop souvent la main en classe se font taquiner. Alors je participe moins devant elles, mais je révise le soir en cachette."]},{"id":"influences","type":"schema","titre":"Les influences sur Samia","source":"Schéma écrit pour l’exercice.","largeur":340,"hauteur":290,"elements":[{"forme":"ligne","de":[170,150],"a":[85,79],"teinte":"gris"},{"forme":"ligne","de":[170,150],"a":[255,79],"teinte":"gris"},{"forme":"ligne","de":[170,150],"a":[170,215],"teinte":"gris"},{"forme":"texte","x":85,"y":32,"texte":"« Les études d’abord »","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"texte","x":255,"y":32,"texte":"« Participe en classe »","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"texte","x":170,"y":280,"texte":"« Ne lève pas la main »","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"rect","x":15,"y":45,"l":140,"h":34,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Ses parents","id":"z1","zone":true},{"forme":"rect","x":185,"y":45,"l":140,"h":34,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Ses professeurs","id":"z2","zone":true},{"forme":"rect","x":100,"y":215,"l":140,"h":34,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Ses copines","id":"z3","zone":true},{"forme":"cercle","cx":170,"cy":150,"r":30,"teinte":"jaune","motif":"plein","texte":"Samia"}]}],"questions":[{"enonce":"Touche l’instance dont le message entre en tension avec celui de sa famille.","aide":"Cherche le message qui décourage de montrer qu’on travaille.","type":"zone","document":"influences","multiple":false},{"enonce":"Samia participe moins devant ses copines mais révise en cachette. Que montre sa conduite ?","aide":"Samia ne suit ni un message, ni l’autre : elle ajuste sa conduite.","type":"choix","options":[{"id":"a","texte":"Elle subit sans réagir le dernier message qu’elle a entendu"},{"id":"b","texte":"Elle a abandonné les normes que sa famille lui avait transmises"},{"id":"c","texte":"Elle choisit et compose entre les messages qu’elle reçoit"},{"id":"d","texte":"Elle a vécu une resocialisation complète de son identité"}],"multiple":false},{"enonce":"Samia a imité sa sœur sans que personne le lui demande. Comment s’appelle ce mode de transmission ?","aide":"Il s’oppose à l’inculcation explicite : on apprend par imitation et exposition répétée.","type":"texte"},{"enonce":"Complète la phrase.","aide":"Les deux messages vont dans des sens opposés ; Samia, elle, compose.","type":"trous","segments":["Ses parents et ses copines lui transmettent des messages ",0," ; pourtant Samia n’est pas un réceptacle ",1,"."],"banque":["actif","convergents","contradictoires","passif"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Le message des **copines** (« ne lève pas la main ») contredit celui des parents (« les études d’abord ») : les instances ne transmettent pas toujours le même message."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’individu n’est pas un réceptacle passif : il **sélectionne, réinterprète et compose** entre les instances."},{"cle":{"type":"texte","acceptes":["impregnation implicite","impregnation","l impregnation implicite","limpregnation implicite"]},"affichage":"imprégnation implicite","explication":"C’est l’**imprégnation implicite** : on apprend en imitant, sans que la règle soit énoncée."},{"cle":{"type":"trous","trous":[["contradictoires"],["passif"]]},"affichage":"contradictoires · passif","explication":"Les messages sont **contradictoires**, et l’individu n’est pas **passif** : il sélectionne et réinterprète."}]$ex$::jsonb),
  ('c9e03eea-0b56-5737-953a-7afef2745dfe'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Maëlys, gardienne de handball et lycéenne","competence":"observer-schema","situation":"Maëlys se présente en quatre appartenances : elle est lycéenne, gardienne de handball, fille d’artisan et habitante d’une petite ville. Le schéma les rassemble autour d’elle.","documents":[{"id":"maelys","type":"schema","titre":"Les appartenances de Maëlys","source":"Schéma écrit pour l’exercice.","largeur":340,"hauteur":260,"elements":[{"forme":"ligne","de":[170,130],"a":[155,52],"teinte":"gris"},{"forme":"ligne","de":[170,130],"a":[185,52],"teinte":"gris"},{"forme":"ligne","de":[170,130],"a":[155,208],"teinte":"gris"},{"forme":"ligne","de":[170,130],"a":[185,208],"teinte":"gris"},{"forme":"rect","x":15,"y":18,"l":140,"h":34,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Lycéenne","id":"z1","zone":true},{"forme":"rect","x":185,"y":18,"l":140,"h":34,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Gardienne de hand","id":"z2","zone":true},{"forme":"rect","x":15,"y":208,"l":140,"h":34,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Fille d’artisan","id":"z3","zone":true},{"forme":"rect","x":185,"y":208,"l":140,"h":34,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Petite ville","id":"z4","zone":true},{"forme":"cercle","cx":170,"cy":130,"r":32,"teinte":"jaune","motif":"plein","texte":"Maëlys"}]}],"questions":[{"enonce":"Touche l’appartenance qui vient de sa famille.","aide":"Cherche le lien avec ses parents.","type":"zone","document":"maelys","multiple":false},{"enonce":"Range chaque groupe : celui auquel Maëlys appartient, ou celui auquel elle aspire.","aide":"Appartenance : on en fait partie. Référence : on voudrait lui ressembler.","type":"categories","categories":[{"id":"c0","texte":"Groupe d’appartenance"},{"id":"c1","texte":"Groupe de référence"}],"items":[{"id":"i0","texte":"Les étudiants en médecine, dont elle adopte déjà le vocabulaire"},{"id":"i1","texte":"L’équipe de France, dont elle copie les gestes et la coiffure"},{"id":"i2","texte":"L’équipe de handball du lycée, dont elle est gardienne"},{"id":"i3","texte":"Sa classe de seconde"}]},{"enonce":"Complète la phrase.","aide":"Elle n’est ni figée ni entièrement choisie : les autres comptent.","type":"trous","segments":["L’identité sociale se construit dans l’",0,", à travers le ",1," des autres."],"banque":["héritage","regard","interaction","hasard"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"L’appartenance « **fille d’artisan** » vient de sa famille."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Le groupe d’**appartenance** est celui où l’on est effectivement ; le groupe de **référence** est celui auquel on aspire et dont on adopte les manières."},{"cle":{"type":"trous","trous":[["interaction","interactions"],["regard"]]},"affichage":"interaction · regard","explication":"L’identité se construit dans l’**interaction**, à travers le **regard** des autres."}]$ex$::jsonb),
  ('c9e03eea-0b56-5737-953a-7afef2745dfe'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre personnes, quatre changements","competence":"lire-tableau","situation":"Une association de quartier a recueilli quatre histoires de personnes dont l’identité a changé. Le tableau les résume.","documents":[{"id":"histoires","type":"tableau","titre":"Quatre histoires","source":"Situations imaginées pour l’exercice.","colonnes":["Personne","Sa situation"],"enteteLignes":true,"lignes":[["Inès, 17 ans","Elle vise une école de commerce et se tient déjà comme les étudiants de cette école."],["Malik, 19 ans","Il entre à l’armée : horaires, langage et valeurs changent profondément."],["Chloé, 34 ans","Infirmière de nuit et mère de deux enfants, elle ne peut pas aller à la fête de l’école le soir où elle travaille."],["Yanis, 20 ans","Futur journaliste, il adopte déjà le ton et les réflexes des reporters qu’il admire."]]}],"questions":[{"enonce":"Touche la situation qui illustre un conflit de rôles.","aide":"Un conflit de rôles oppose les attentes de deux positions occupées en même temps.","type":"zone","document":"histoires","multiple":false},{"enonce":"Range chaque personne selon le processus que sa situation illustre.","aide":"Anticipatrice : on prend d’avance les codes d’un rôle futur. Resocialisation : transformation profonde.","type":"categories","categories":[{"id":"c0","texte":"Socialisation anticipatrice"},{"id":"c1","texte":"Resocialisation"},{"id":"c2","texte":"Conflit de rôles"}],"items":[{"id":"i0","texte":"Yanis (futur journaliste)"},{"id":"i1","texte":"Chloé (infirmière et mère)"},{"id":"i2","texte":"Malik (armée)"},{"id":"i3","texte":"Inès (école de commerce)"}]},{"enonce":"Pourquoi l’entrée de Malik à l’armée est-elle une resocialisation et non une simple anticipation ?","aide":"Compare l’ampleur du changement : léger ajustement ou transformation profonde ?","type":"choix","options":[{"id":"a","texte":"Elle transforme profondément ses normes et ses rôles intériorisés"},{"id":"b","texte":"Elle prolonge simplement la socialisation de son enfance"},{"id":"c","texte":"Elle oppose deux positions qu’il occupe en même temps"},{"id":"d","texte":"Elle prépare d’avance un rôle qu’il n’occupe pas encore"}],"multiple":false},{"enonce":"Combien de ces quatre personnes adoptent d’avance les codes d’un rôle futur ?","aide":"Cherche celles qui se préparent à un groupe ou un métier qu’elles n’ont pas encore rejoint.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Chloé est à la fois **infirmière et mère** : les attentes de ses deux positions se contredisent ce soir-là."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c0"}},"explication":"Inès et Yanis adoptent **d’avance** les codes d’un groupe visé ; Malik subit une **resocialisation** ; Chloé vit un **conflit de rôles**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Une **resocialisation** transforme profondément les normes et rôles intériorisés ; entrer à l’armée en est l’exemple type."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"**Deux** personnes pratiquent la socialisation anticipatrice : Inès et Yanis."}]$ex$::jsonb),
  ('c9e03eea-0b56-5737-953a-7afef2745dfe'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Mêmes notes, deux orientations","competence":"raisonner","situation":"Théo et Romane sont dans la même classe de première, avec la même moyenne. Pourtant, ils n’envisagent pas la même orientation. Le tableau rapporte leurs propos ; le schéma de causes cherche à expliquer pourquoi.","documents":[{"id":"duo","type":"tableau","titre":"Deux élèves, mêmes résultats","source":"Situation et propos imaginés pour l’exercice.","colonnes":["","Théo","Romane"],"enteteLignes":true,"lignes":[["Moyenne générale","15,5 / 20","15,5 / 20"],["Profession des parents","Cadres supérieurs","Ouvrier et aide-soignante"],["Orientation envisagée","Classe préparatoire","BTS puis emploi rapide"],["Ce qu’ils disent","« La prépa, c’est normal dans ma famille. »","« La prépa, ce n’est pas pour des gens comme nous. »"]]},{"id":"causes","type":"chaine","titre":"Le choix de Théo","source":"Schéma écrit pour l’exercice.","disposition":"colonne","noeuds":[{"id":"z1","texte":"Une famille qui valorise les études longues"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Il se sent à sa place en prépa"},{"id":"z4","texte":"Il choisit la prépa"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Quel est l’écart entre les moyennes de Théo et de Romane ?","aide":"Compare les deux cases de la première ligne.","type":"nombre"},{"enonce":"Touche la case qui montre que Romane se sent moins légitime en prépa.","aide":"Cherche la phrase qui parle de « gens comme nous ».","type":"zone","document":"duo","multiple":false},{"enonce":"Quel maillon manque dans le schéma de causes ?","aide":"Le milieu transmet des manières de penser et de sentir qui orientent sans que l’élève y pense.","type":"choix","options":[{"id":"a","texte":"Des dispositions socialisées, un habitus, qui orientent ce qu’il juge possible"},{"id":"b","texte":"Une décision du conseil de classe qui le dispense de choisir"},{"id":"c","texte":"Un règlement de l’établissement qui lui impose de choisir la prépa"},{"id":"d","texte":"Un écart de notes qui le place devant Romane dans la classe"}],"multiple":false},{"enonce":"Que montre cet exemple sur la reproduction sociale ?","aide":"Aucun règlement n’interdit la prépa à Romane. Pourtant…","type":"choix","options":[{"id":"a","texte":"Les familles imposent explicitement le choix des études à leurs enfants dès la seconde"},{"id":"b","texte":"La mobilité sociale est impossible pour tous les enfants d’ouvriers sans exception"},{"id":"c","texte":"Les positions sociales se transmettent en partie, sans qu’aucune règle ne l’impose"},{"id":"d","texte":"Les notes seules suffisent à déterminer l’orientation de chaque élève dans le système scolaire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0,"tolerance":0},"affichage":"0","explication":"Les deux élèves ont **la même moyenne** : l’écart est nul. Leurs notes n’expliquent donc pas la différence d’orientation."},{"cle":{"type":"zone","ids":["r3c2"]},"explication":"Romane se sent exclue d’un milieu qui n’est « pas pour des gens comme nous » : c’est le poids de la **trajectoire sociale**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le maillon est l’**habitus** de Bourdieu : un ensemble de dispositions incorporées qui orientent les pratiques sans qu’on ait besoin d’y penser."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les dispositions socialisées font que **les positions se reproduisent en partie**, sans règle explicite et sans interdire la mobilité."}]$ex$::jsonb),
  ('24604193-0057-5f52-a210-9ca28202a90e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui s’inscrit dans quelle filière ?","competence":"lire-graphique","situation":"Au forum d’orientation du lycée, une professeure affiche la part de filles dans trois formations. Elle demande aux élèves ce que cela révèle de la socialisation.","documents":[{"id":"filieres","type":"graphique","forme":"barres","titre":"Part de filles dans trois formations","source":"Chiffres arrondis imaginés pour l’exercice, proches des ordres de grandeur réels.","categories":["Santé","Lettres","Informatique"],"series":[{"nom":"Part de filles (%)","valeurs":[75,80,15],"teinte":"violet"}],"axeY":{"titre":"Part de filles","unite":"%","min":0,"max":100,"pas":20},"valeurs":false}],"questions":[{"enonce":"Touche la formation où les filles sont très minoritaires.","aide":"Cherche la barre la plus basse.","type":"zone","document":"filieres","multiple":false},{"enonce":"En Lettres, quelle est la part de garçons, en pourcentage ?","aide":"Les filles et les garçons font 100 % à eux deux.","type":"nombre","unite":"%"},{"enonce":"Relie chaque mot à sa définition.","aide":"L’un est biologique, l’autre est construit par la société.","type":"association","gauche":[{"id":"g0","texte":"Le sexe"},{"id":"g1","texte":"Le genre"},{"id":"g2","texte":"La socialisation différenciée"}],"droite":[{"id":"d0","texte":"Les rôles et attributs socialement associés au masculin et au féminin"},{"id":"d1","texte":"Les caractéristiques biologiques"},{"id":"d2","texte":"Des attentes et des encouragements qui varient selon le sexe de l’enfant"}]}]}$ex$::jsonb,
