  ('24604193-0057-5f52-a210-9ca28202a90e'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le partage des tâches chez les Morel","competence":"lire-tableau","situation":"Les Morel ont noté pendant une semaine le temps que chacun passe, en moyenne par jour, aux tâches de la maison. Marc, leur fils de 6 ans, observe tout ce qui se passe.","documents":[{"id":"taches","type":"tableau","titre":"Temps domestique moyen par jour (en minutes)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Tâche","Mère","Père"],"enteteLignes":true,"lignes":[["Repas",55,30],["Ménage et linge",60,25],["Courses",20,20],["Enfants (soins, devoirs)",50,25],["Bricolage et jardin",5,20]]},{"id":"scene","type":"texte","genre":"recit","titre":"Une scène de la vie de Marc","auteur":"Texte écrit pour l’exercice","blocs":["Quand Marc, 6 ans, se fait mal en tombant, son père lui dit : « Un garçon, ça ne pleure pas. » Sa sœur Lila, 6 ans aussi, est aussitôt consolée dans les bras de sa mère."]}],"questions":[{"enonce":"Combien de minutes par jour la mère consacre-t-elle en tout à ces cinq tâches ?","aide":"Additionne la colonne « Mère ».","type":"nombre","unite":"min"},{"enonce":"Quel écart de temps y a-t-il entre la mère et le père sur l’ensemble des tâches ?","aide":"Calcule d’abord le total du père (120 minutes).","type":"nombre","unite":"min"},{"enonce":"Touche la seule tâche où le père passe plus de temps que la mère.","aide":"Compare les deux colonnes ligne par ligne.","type":"zone","document":"taches","multiple":false},{"enonce":"Touche le mot qui fixe une norme selon le sexe de l’enfant.","aide":"Quel mot de la phrase du père renvoie à une catégorie de sexe ?","type":"zone","document":"scene","multiple":false},{"enonce":"Si ce partage des tâches était purement biologique, que devrait-on observer selon les pays et les époques ?","aide":"Ce qui est biologique ne varie pas d’une société à l’autre.","type":"choix","options":[{"id":"a","texte":"Un partage qui s’inverse à chaque siècle"},{"id":"b","texte":"Le même partage partout et à toutes les époques"},{"id":"c","texte":"Un partage qui change d’une génération à l’autre"},{"id":"d","texte":"Un partage qui dépend du revenu des familles"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":190,"tolerance":0},"affichage":"190 min","explication":"55 + 60 + 20 + 50 + 5 = **190 minutes**."},{"cle":{"type":"nombre","valeur":70,"tolerance":0},"affichage":"70 min","explication":"Le père totalise 30 + 25 + 20 + 25 + 20 = 120 minutes. 190 − 120 = **70 minutes** : la répartition est inégale."},{"cle":{"type":"zone","ids":["r4c0"]},"explication":"Pour le **bricolage et le jardin**, le père consacre 20 minutes contre 5 pour la mère."},{"cle":{"type":"zone","ids":["m14"]},"explication":"Le mot « **garçon** » rattache une règle (ne pas pleurer) au sexe de l’enfant : c’est de la socialisation de genre."},{"cle":{"type":"choix","ids":["b"]},"explication":"Un partage biologique serait **le même partout**. Comme il varie selon les époques et les pays, il est socialement construit."}]$ex$::jsonb),
  ('24604193-0057-5f52-a210-9ca28202a90e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux foyers, deux rapports à la culture","competence":"analyser-document","situation":"Une enquête imaginée compare deux types de familles. Une conseillère d’orientation en tire des conclusions sur la réussite scolaire, puis Leïla et Hugo, deux élèves de seconde, racontent leur point de vue.","documents":[{"id":"enquete","type":"tableau","titre":"Pratiques des familles (en %)","source":"Enquête imaginée pour l’exercice.","colonnes":["Pratique","Familles de cadres","Familles d’ouvriers"],"enteteLignes":true,"lignes":[["Plus de 100 livres à la maison",70,25],["Sortie au musée ou au théâtre au moins une fois par an",80,30],["Discussion sur les devoirs presque tous les soirs",85,60]]},{"id":"eleves","type":"texte","genre":"recit","titre":"Leïla et Hugo","auteur":"Témoignages écrits pour l’exercice","blocs":["Hugo : « Chez moi, on parle de mes devoirs au dîner et on va souvent au musée. Les études longues, c’est une évidence. »","Leïla : « Mes parents me soutiennent, mais ils ne connaissent pas les filières. Je ne sais pas si ce serait pour moi. »"]}],"questions":[{"enonce":"Touche la pratique où l’écart entre les deux types de familles est le plus grand.","aide":"Calcule l’écart de chaque ligne, en points de pourcentage.","type":"zone","document":"enquete","multiple":false},{"enonce":"Combien de fois plus souvent les familles de cadres ont-elles plus de 100 livres que les familles d’ouvriers ? Divise 70 par 25.","aide":"Divise 70 par 25.","type":"nombre"},{"enonce":"Relie chaque pratique à la dimension de l’éducation qu’elle illustre.","aide":"Chaque ligne du tableau correspond à un domaine où les pratiques éducatives varient.","type":"association","gauche":[{"id":"g0","texte":"Plus de 100 livres à la maison"},{"id":"g1","texte":"Sorties au musée ou au théâtre"},{"id":"g2","texte":"Discussion sur les devoirs"}],"droite":[{"id":"d0","texte":"Le rapport à l’école"},{"id":"d1","texte":"Les loisirs"},{"id":"d2","texte":"Le rapport à la lecture"}]},{"enonce":"Touche le mot qui renvoie à ce qu’Hugo considère comme normal pour son avenir.","aide":"Quel mot désigne ce qui est « une évidence » pour Hugo ?","type":"zone","document":"eleves","multiple":false},{"enonce":"Quel terme de Bourdieu désigne les savoirs, références et aisances transmis par la famille et valorisés à l’école ?","aide":"Les familles de cadres l’ont souvent en abondance.","type":"choix","options":[{"id":"a","texte":"Le capital financier"},{"id":"b","texte":"Le capital symbolique"},{"id":"c","texte":"Le capital culturel"},{"id":"d","texte":"Le capital social"}],"multiple":false}]}$ex$::jsonb,
