  ('774f4dad-c5f7-5246-9004-37176c8e7ff3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois pays, une question : démocratie ou pas ?","competence":"lire-tableau","situation":"Au club d’actualité du lycée, Anaïs compare trois pays imaginés. Elle veut savoir lesquels méritent le nom de démocratie. Le tableau résume ce qu’elle a relevé.","documents":[{"id":"pays","type":"tableau","titre":"Trois pays imaginés","source":"Pays et situations imaginés pour l’exercice.","colonnes":["Critère","Arvia","Boranie","Cestal"],"enteteLignes":true,"lignes":[["Élections libres et pluralistes","Oui","Oui","Non"],["Presse libre","Oui","Non","Non"],["Justice indépendante","Oui","Non","Non"],["Alternance possible","Oui","Non","Non"]]}],"questions":[{"enonce":"Touche la case qui montre qu’en Boranie, malgré des élections, la liberté de la presse n’est pas respectée.","aide":"Cherche la ligne « Presse libre », puis la colonne de Boranie.","type":"zone","document":"pays","multiple":false},{"enonce":"Quel régime décrit le mieux la Boranie ?","aide":"Des élections existent, mais d’autres critères sont absents.","type":"choix","options":[{"id":"a","texte":"Une démocratie participative fondée sur des consultations"},{"id":"b","texte":"Une démocratie directe où les citoyens décident eux-mêmes"},{"id":"c","texte":"Une démocratie complète, puisque des élections ont lieu"},{"id":"d","texte":"Un régime hybride : élections maintenues, libertés vidées"}],"multiple":false},{"enonce":"Relie chaque critère démocratique à son contenu.","aide":"Chaque critère répond à une question : d’où vient le pouvoir, qui le partage, qui doit obéir à la loi ?","type":"association","gauche":[{"id":"g0","texte":"La souveraineté du peuple"},{"id":"g1","texte":"La séparation des pouvoirs"},{"id":"g2","texte":"L’État de droit"}],"droite":[{"id":"d0","texte":"Chacun, gouvernants compris, est soumis à la loi"},{"id":"d1","texte":"Le pouvoir vient des citoyens"},{"id":"d2","texte":"Exécutif, législatif et judiciaire sont distincts"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"En Boranie, la presse n’est **pas libre** : organiser des élections ne suffit pas à faire une démocratie."},{"cle":{"type":"choix","ids":["d"]},"explication":"Un régime qui garde les élections en vidant les libertés est un **régime hybride**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Souveraineté du peuple** : le pouvoir vient des citoyens. **Séparation des pouvoirs** : trois pouvoirs distincts. **État de droit** : tous sont soumis à la loi."}]$ex$::jsonb),
  ('774f4dad-c5f7-5246-9004-37176c8e7ff3'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le budget participatif de Port-Sainte-Anne","competence":"resoudre","situation":"À Port-Sainte-Anne, ville imaginée, les habitants votent pour choisir des projets financés par la mairie. Il faut comprendre l’affiche, puis voir quels projets seront réalisés.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Port-Sainte-Anne : à vous de décider !","sousTitre":"Budget participatif","emoji":"🗳️","source":"Affiche imaginée pour l’exercice.","lignes":[{"texte":"Budget d’investissement de la ville","valeur":"2 400 000 €"},{"texte":"Part réservée aux projets des habitants","valeur":"5 %","id":"z1"},{"separateur":true},{"texte":"Règle : les projets sont financés dans l’ordre des votes, tant qu’il reste assez d’argent. Un projet trop cher pour la somme restante est passé.","id":"z2"}],"pied":"Résultats affichés en mairie."},{"id":"votes","type":"tableau","titre":"Résultats du vote","source":"Chiffres imaginés pour l’exercice.","colonnes":["Projet","Votes","Coût (€)"],"enteteLignes":true,"lignes":[["Jardin partagé",410,60000],["Pump track",530,70000],["Abri à vélos",360,45000]]}],"questions":[{"enonce":"Touche la ligne de l’affiche qui donne la part du budget laissée aux habitants.","aide":"Cherche un pourcentage.","type":"zone","document":"affiche","multiple":false},{"enonce":"Quelle somme, en euros, les habitants ont-ils à répartir ?","aide":"Calcule 5 % de 2 400 000 €, soit 2 400 000 × 0,05.","type":"nombre","unite":"€"},{"enonce":"Quels projets seront réalisés, selon la règle de l’affiche ?","aide":"Classe les projets par nombre de votes, puis retire leur coût de la somme disponible, projet après projet.","type":"choix","options":[{"id":"a","texte":"L’abri à vélos"},{"id":"b","texte":"Le pump track"},{"id":"c","texte":"Le jardin partagé"}],"multiple":true},{"enonce":"Quelle part des 1 300 votes le pump track a-t-il obtenue ? Arrondis à l’unité.","aide":"Divise 530 par 1 300, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Range chaque dispositif selon la forme de démocratie qu’il illustre.","aide":"Direct : le citoyen décide lui-même. Représentatif : il élit. Participatif : il s’exprime entre deux élections.","type":"categories","categories":[{"id":"c0","texte":"Directe"},{"id":"c1","texte":"Représentative"},{"id":"c2","texte":"Participative"}],"items":[{"id":"i0","texte":"Une convention citoyenne tirée au sort"},{"id":"i1","texte":"L’élection d’un conseil municipal"},{"id":"i2","texte":"Un budget participatif"},{"id":"i3","texte":"Un référendum"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est la ligne « **5 %** » : seule une petite part du budget est décidée par les habitants."},{"cle":{"type":"nombre","valeur":120000,"tolerance":0},"affichage":"120 000 €","explication":"5 % de 2 400 000 € = **120 000 €**."},{"cle":{"type":"choix","ids":["a","b"]},"explication":"Le pump track (70 000 €) passe en tête ; il reste 50 000 €. Le jardin (60 000 €) est trop cher et est passé. L’abri à vélos (45 000 €) rentre : **pump track et abri à vélos**."},{"cle":{"type":"nombre","valeur":41,"tolerance":0},"affichage":"41 %","explication":"530 ÷ 1 300 ≈ 0,408, soit environ **41 %** des votes."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c2","i3":"c0"}},"explication":"Un **référendum** est direct ; un conseil municipal **élu** est représentatif ; le **budget participatif** et la convention citoyenne associent les citoyens entre deux élections : c’est du participatif."}]$ex$::jsonb),
  ('774f4dad-c5f7-5246-9004-37176c8e7ff3'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"À Norland, on vote… mais pas seulement","competence":"analyser-document","situation":"Dans le pays imaginé de Norland, des élections ont lieu régulièrement. Un journaliste étranger analyse un article local et un graphique de participation.","documents":[{"id":"article","type":"texte","genre":"article","titre":"À Norland, des élections sans alternative ?","auteur":"Article imaginé pour l’exercice","blocs":["Les élections ont lieu tous les cinq ans à Norland, et chaque électeur peut glisser un bulletin dans l’urne. Pourtant, depuis la dernière réélection, le seul journal indépendant du pays a été fermé pour « atteinte à l’ordre public ».","Des juges de la Cour suprême ont été remplacés par des proches du gouvernement, et plusieurs associations de défense des droits ont été dissoutes. L’opposition dénonce un régime où l’on vote encore, mais où l’on ne peut plus informer, juger ni contester librement."]},{"id":"participation","type":"graphique","forme":"courbe","titre":"Participation aux élections de Norland","source":"Chiffres imaginés pour l’exercice.","categories":["2004","2009","2014","2019","2024"],"series":[{"nom":"Participation (%)","valeurs":[70,66,61,55,48],"teinte":"turquoise"}],"axeY":{"titre":"Participation","unite":"%","min":40,"max":80,"pas":10},"axeX":{"titre":"Année de l’élection"}}],"questions":[{"enonce":"Touche la première élection où la participation passe sous la barre des 50 %.","aide":"Cherche le premier point situé sous 50.","type":"zone","document":"participation","multiple":false},{"enonce":"De combien de points de pourcentage la participation a-t-elle baissé entre 2004 et 2024 ?","aide":"Soustrais la valeur de 2024 à celle de 2004.","type":"nombre","unite":"points"},{"enonce":"De quel pourcentage la participation a-t-elle baissé entre 2004 et 2024 ? Arrondis à l’unité.","aide":"Divise la baisse en points (22) par la valeur de départ (70).","type":"nombre","unite":"%"},{"enonce":"Relie chaque mesure de Norland à ce qu’elle permet au pouvoir de faire.","aide":"Presse, justice, associations : chacune est un contre-pouvoir qui empêche quelque chose.","type":"association","gauche":[{"id":"g0","texte":"Fermeture du seul journal indépendant"},{"id":"g1","texte":"Remplacement de juges de la Cour suprême"},{"id":"g2","texte":"Dissolution d’associations de défense des droits"}],"droite":[{"id":"d0","texte":"Échapper à l’impunité"},{"id":"d1","texte":"Garder le secret"},{"id":"d2","texte":"Confisquer le débat"}]},{"enonce":"Comment appelle-t-on un régime qui garde les élections tout en vidant les libertés ? Donne l’adjectif.","aide":"L’adjectif désigne un mélange de deux natures.","type":"texte"},{"enonce":"Quelle fragilité des démocraties la baisse de participation illustre-t-elle ?","aide":"Le graphique parle des électeurs qui ne vont pas voter.","type":"choix","options":[{"id":"a","texte":"La désinformation, qui fausse le débat public"},{"id":"b","texte":"L’abstention, qui déforme la représentation"},{"id":"c","texte":"L’inégalité d’accès à la parole publique"},{"id":"d","texte":"Le financement opaque des campagnes électorales"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"En **2024**, la participation tombe à 48 % : c’est la première fois qu’elle passe sous 50 %."},{"cle":{"type":"nombre","valeur":22,"tolerance":0},"affichage":"22 points","explication":"70 − 48 = **22 points** de pourcentage."},{"cle":{"type":"nombre","valeur":31,"tolerance":0},"affichage":"31 %","explication":"22 ÷ 70 ≈ 0,314 : une baisse d’environ **31 %**. Attention : 22 points et 31 % ne désignent pas la même chose."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Sans presse libre, le **secret** est possible ; sans justice indépendante, l’**impunité** ; sans associations, le débat est **confisqué**."},{"cle":{"type":"texte","acceptes":["hybride","regime hybride","un regime hybride"]},"affichage":"hybride","explication":"Norland est un **régime hybride** : les élections subsistent, mais les contre-pouvoirs sont affaiblis."},{"cle":{"type":"choix","ids":["b"]},"explication":"Quand la participation baisse, c’est l’**abstention** qui progresse : les élus représentent alors une part plus faible des citoyens."}]$ex$::jsonb),
