   $ex${"titre":"Léna fait-elle un bon calcul ?","competence":"modeliser","situation":"Louis travaille dès 18 ans. Léna fait trois ans d’études avant de travailler. Le tableau donne les hypothèses, le graphique l’écart de revenu cumulé de Léna par rapport à Louis.","documents":[{"id":"hypotheses","type":"tableau","titre":"Louis et Léna : les hypothèses","source":"Hypothèses imaginées pour l’exercice.","colonnes":["","Louis","Léna"],"enteteLignes":true,"lignes":[["Salaire net mensuel de 18 à 21 ans","1 400 €","0 € (études)"],["Frais d’études sur trois ans","0 €","3 600 €"],["Salaire net mensuel à partir de 21 ans","1 400 €","1 900 €"]]},{"id":"ecart","type":"graphique","forme":"courbe","titre":"Revenu cumulé de Léna par rapport à Louis","source":"Calculs imaginés pour l’exercice, en milliers d’euros.","categories":["18 ans","21 ans","24 ans","27 ans","30 ans","33 ans"],"series":[{"nom":"Écart cumulé (milliers d’€)","valeurs":[0,-54,-36,-18,0,18],"teinte":"violet"}],"axeY":{"titre":"Écart cumulé","unite":"en milliers d’euros","min":-60,"max":20,"pas":20},"axeX":{"titre":"Âge"}}],"questions":[{"enonce":"Touche l’âge auquel Léna rattrape Louis.","aide":"Cherche le point où l’écart cumulé revient à zéro.","type":"zone","document":"ecart","multiple":false},{"enonce":"Quel salaire Léna ne perçoit-elle pas pendant ses trois années d’études ? Réponds en euros.","aide":"Multiplie 1 400 € par le nombre de mois d’études (36).","type":"nombre","unite":"€"},{"enonce":"Avec les frais d’études, Léna perd 54 000 €. Combien de mois de salaire supplémentaire (500 € par mois) lui faut-il pour les récupérer ?","aide":"Divise 54 000 par 500.","type":"nombre","unite":"mois"},{"enonce":"Quel avantage de l’investissement de Léna ce calcul ne prend-il pas en compte ?","aide":"Le calcul ne compare que des euros de salaire et de frais.","type":"choix","options":[{"id":"a","texte":"Le montant des frais d’inscription et du matériel scolaire"},{"id":"b","texte":"La différence de salaire mensuel entre Léna et Louis"},{"id":"c","texte":"Un risque de chômage plus faible et une carrière plus ascendante"},{"id":"d","texte":"Le coût d’opportunité des trois années passées à étudier"}],"multiple":false},{"enonce":"Relie chaque affirmation à la théorie qu’elle illustre.","aide":"L’une parle de productivité, l’autre d’information, la dernière d’un décalage entre diplôme et poste.","type":"association","gauche":[{"id":"g0","texte":"La formation rend réellement plus productif"},{"id":"g1","texte":"Le diplôme informe sur la persévérance du candidat"},{"id":"g2","texte":"Occuper un emploi moins qualifié que son diplôme"}],"droite":[{"id":"d0","texte":"Théorie du capital humain"},{"id":"d1","texte":"Déclassement"},{"id":"d2","texte":"Théorie du signal"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"À **30 ans**, l’écart cumulé est nul : Léna a rattrapé Louis."},{"cle":{"type":"nombre","valeur":50400,"tolerance":0},"affichage":"50 400 €","explication":"36 × 1 400 € = **50 400 €** : c’est le coût d’opportunité."},{"cle":{"type":"nombre","valeur":108,"tolerance":0},"affichage":"108 mois","explication":"54 000 ÷ 500 = **108 mois**, soit 9 ans après ses 21 ans : à 30 ans."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le calcul ne chiffre que salaires et frais ; il ignore le **risque de chômage plus faible** et une **carrière plus ascendante**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Capital humain : productivité réelle. Signal : information sur des qualités. **Déclassement** : emploi moins qualifié que le diplôme."}]$ex$::jsonb),
  ('d86f45b5-6282-5658-8d73-973c1c8461a3'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Qui est chômeur à Valbrun ?","competence":"lire-tableau","situation":"La commune imaginée de Valbrun veut compter ses chômeurs. Pour cela, elle utilise la définition du Bureau international du travail (BIT). Deux tableaux résument la situation.","documents":[{"id":"personnes","type":"tableau","titre":"Quatre habitants de Valbrun","source":"Situations imaginées pour l’exercice.","colonnes":["Personne","Sans emploi","Disponible","Recherche active"],"enteteLignes":true,"lignes":[["Nina","Oui","Oui","Oui"],["Théo","Oui","Oui","Non"],["Lucie","Non","Oui","Non"],["Hugo","Oui","Non","Oui"]]},{"id":"commune","type":"tableau","titre":"La population de Valbrun","source":"Chiffres imaginés pour l’exercice.","colonnes":["Catégorie","Personnes"],"enteteLignes":true,"lignes":[["Actifs occupés",900],["Chômeurs",100],["Autres (élèves, retraités…)",1000],["Population totale",2000]]}],"questions":[{"enonce":"Touche la personne qui est chômeuse au sens du BIT.","aide":"Il faut remplir les trois conditions : sans emploi, disponible, en recherche active.","type":"zone","document":"personnes","multiple":false},{"enonce":"Pourquoi Théo n’est-il pas chômeur au sens du BIT ?","aide":"Compare les trois colonnes de sa ligne.","type":"choix","options":[{"id":"a","texte":"Il ne cherche pas activement un emploi"},{"id":"b","texte":"Il occupe déjà un emploi stable"},{"id":"c","texte":"Il n’est pas disponible pour travailler"},{"id":"d","texte":"Il n’a jamais travaillé auparavant"}],"multiple":false},{"enonce":"Quelle est la population active de Valbrun ?","aide":"La population active, ce sont les actifs occupés plus les chômeurs.","type":"nombre","unite":"personnes"},{"enonce":"Quel est le taux de chômage de Valbrun, en pourcentage ?","aide":"Divise le nombre de chômeurs par la population active, et non par la population totale.","type":"nombre","unite":"%"}]}$ex$::jsonb,
