   $ex${"titre":"Quarante soudeurs cherchés, cent vingt chômeurs inscrits","competence":"analyser-document","situation":"À Vallée-Haute, une fonderie ne trouve pas de salariés alors que le chômage reste élevé. Un article et un graphique aident à comprendre cette contradiction apparente.","documents":[{"id":"article","type":"texte","genre":"article","titre":"La fonderie cherche, les chômeurs attendent","auteur":"Article imaginé pour l’exercice","blocs":["La fonderie Altia cherche depuis un an quarante soudeurs qualifiés. L’agence pour l’emploi compte pourtant cent vingt chômeurs inscrits dans le bassin, mais aucun ne possède la qualification demandée.","« Nous formons sur le tas quand nous le pouvons, mais ce métier exige plusieurs années de pratique », explique la direction."]},{"id":"diplomes","type":"graphique","forme":"barres","titre":"Taux de chômage selon le diplôme","source":"Chiffres imaginés pour l’exercice.","categories":["Sans diplôme","CAP-BEP","Baccalauréat","Diplôme du supérieur"],"series":[{"nom":"Taux de chômage (%)","valeurs":[17,10,7,5],"teinte":"corail"}],"axeY":{"titre":"Taux de chômage","unite":"%","min":0,"max":20,"pas":5},"valeurs":false}],"questions":[{"enonce":"Touche le niveau de diplôme dont le taux de chômage est le plus élevé.","aide":"Cherche la barre la plus haute.","type":"zone","document":"diplomes","multiple":false},{"enonce":"Combien de fois le taux de chômage des non-diplômés est-il supérieur à celui des diplômés du supérieur ?","aide":"Divise 17 par 5.","type":"nombre"},{"enonce":"Relie chaque situation au type de chômage qu’elle illustre.","aide":"Qualifications, demande, temps de recherche : trois origines différentes.","type":"association","gauche":[{"id":"g0","texte":"Des soudeurs introuvables malgré des chômeurs"},{"id":"g1","texte":"Les commandes baissent dans toute l’économie"},{"id":"g2","texte":"Une étudiante met trois mois à trouver son premier poste"}],"droite":[{"id":"d0","texte":"Chômage conjoncturel"},{"id":"d1","texte":"Chômage frictionnel"},{"id":"d2","texte":"Chômage structurel"}]},{"enonce":"Quelle politique vise d’abord le chômage de la fonderie Altia ?","aide":"Le problème vient des qualifications, pas du manque de commandes.","type":"choix","options":[{"id":"a","texte":"La formation et l’apprentissage"},{"id":"b","texte":"Le soutien à la demande"},{"id":"c","texte":"Une hausse du salaire minimum pour tous"},{"id":"d","texte":"Un allègement général des impôts sur les sociétés"}],"multiple":false}]}$ex$::jsonb,
