à la politique la mieux adaptée.","aide":"Demande, qualifications, coût du travail : trois causes, trois remèdes.","type":"association","gauche":[{"id":"g0","texte":"Marlieux"},{"id":"g1","texte":"Rochebrune"},{"id":"g2","texte":"Saint-Orme"}],"droite":[{"id":"d0","texte":"Formation et apprentissage"},{"id":"d1","texte":"Allègement des cotisations sur les bas salaires"},{"id":"d2","texte":"Soutien à la demande"}]},{"enonce":"Quel est le taux de chômage de Marlieux, en pourcentage ?","aide":"Divise 1 200 par 12 000.","type":"nombre","unite":"%"},{"enonce":"Pourquoi une politique de formation ne suffirait-elle pas à régler le chômage de Marlieux ?","aide":"Rappelle-toi la cause du chômage à Marlieux : manque de commandes ou manque de qualifications ?","type":"choix","options":[{"id":"a","texte":"Le problème est un manque de demande, pas de qualifications"},{"id":"b","texte":"La formation augmente automatiquement le coût du travail"},{"id":"c","texte":"Le chômage conjoncturel n’existe pas dans les petites villes"},{"id":"d","texte":"Les habitants de Marlieux refusent toute formation proposée"}],"multiple":false}]}$ex$::jsonb,
