HTTP"},{"id":"g1","texte":"TCP"},{"id":"g2","texte":"IP"},{"id":"g3","texte":"Wifi ou fibre"}],"droite":[{"id":"d0","texte":"Transport"},{"id":"d1","texte":"Internet"},{"id":"d2","texte":"Application"},{"id":"d3","texte":"Accès réseau"}]},{"enonce":"Les courriels de Malik arrivent. Que peut-on en déduire ?","aide":"Le courriel utilise Internet sans passer par le Web.","type":"choix","options":[{"id":"a","texte":"Internet est en panne, donc le Web aussi"},{"id":"b","texte":"Le courriel est une partie du Web"},{"id":"c","texte":"Le Web et Internet sont une seule chose"},{"id":"d","texte":"Internet marche, la panne est côté Web"}],"multiple":false}]}$ex$::jsonb,
